using Clary.Api.Identity;
using NpgsqlTypes;
namespace Clary.Api;
public sealed partial class TicketRepository {
 public async Task<TicketDto> ActionAsync(CompanyContext c,Guid id,TicketActionInput input,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);var result=await ActionWithin(conn,tx,c,id,input,ct);await tx.CommitAsync(ct);return result;
 }
 internal async Task<TicketDto> ActionWithin(Npgsql.NpgsqlConnection conn,Npgsql.NpgsqlTransaction tx,CompanyContext c,Guid id,TicketActionInput input,CancellationToken ct){
  await Lock(conn,tx,c,id,ct);var before=await Get(conn,tx,c,id,ct)??throw new InventoryMissing();if(before.Revision!=input.Revision)throw new InventoryConflict("This ticket changed. Refresh before acting.");if(!before.AllowedActions.Contains(input.Action))throw new InventoryConflict("This action is not available for this ticket.");
  if(input.Action=="priority"){if(input.Priority is null||!new[]{"Low","Normal","High","Urgent"}.Contains(input.Priority))throw new ArgumentException("Choose a valid priority.");await using var update=Q(conn,tx,c,"UPDATE equipment_tickets SET priority=@priority,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@id");update.Parameters.AddWithValue("priority",input.Priority);update.Parameters.AddWithValue("id",id);await update.ExecuteNonQueryAsync(ct);await Activity(conn,tx,c,id,"Priority changed",input.Priority,ct);var priorityUpdated=(await Get(conn,tx,c,id,ct))!;await AuditRepository.AppendAsync(conn,tx,c,"Priority changed","equipment-ticket",id,before,priorityUpdated,ct);return priorityUpdated;}
  if(input.Action=="delete"){await using var remove=Q(conn,tx,c,"UPDATE equipment_tickets SET dismissed=true,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@id AND is_workspace_setup");remove.Parameters.AddWithValue("id",id);await remove.ExecuteNonQueryAsync(ct);await Activity(conn,tx,c,id,"Deleted","Optional setup ticket dismissed",ct);var deleted=before with{Revision=before.Revision+1,AllowedActions=[]};await AuditRepository.AppendAsync(conn,tx,c,"Deleted","equipment-ticket",id,before,deleted,ct);return deleted;}
  var status=input.Action switch{"approve"=>before.AssignmentMode=="All"||before.Assignees.Count>0?"Assigned":"Approved","start"=>"In Progress","send-for-repair"=>"In Progress","complete"=>"Complete","cancel"=>"Canceled",_=>throw new ArgumentException("Unknown action.")};
  if(input.Action=="complete"&&input.AssetIds is not null)await Fulfillment(conn,tx,c,before,input.AssetIds,ct);
  await ApplyInventory(conn,tx,c,before,input.Action,ct);
  await using(var q=Q(conn,tx,c,"UPDATE equipment_tickets SET state=@state,revision=revision+1,updated_at=now(),approver_user_id=CASE WHEN @approve THEN @user ELSE approver_user_id END,approver_name=CASE WHEN @approve THEN @actor ELSE approver_name END,approved_at=CASE WHEN @approve THEN now() ELSE approved_at END WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("state",status);q.Parameters.AddWithValue("approve",input.Action=="approve");q.Parameters.AddWithValue("actor",await Actor(conn,tx,c,ct));q.Parameters.AddWithValue("id",id);await q.ExecuteNonQueryAsync(ct);}
  if(before.RequestId is {} request){await using var q=Q(conn,tx,c,"UPDATE equipment_requests SET state=@state,revision=revision+1 WHERE company_id=@company AND id=@request; INSERT INTO equipment_request_assets(company_id,request_id,asset_id) SELECT company_id,@request,asset_id FROM ticket_asset_links WHERE company_id=@company AND ticket_id=@ticket AND outcome='Assign' AND owned_revision IS NOT NULL ON CONFLICT DO NOTHING");q.Parameters.AddWithValue("state",status switch{"Complete"=>"Completed","Canceled"=>"Cancelled","Assigned" or "In Progress"=>before.Assets.Any(a=>a.Outcome=="Assign"&&a.Status=="Assigned")?"Ready":"Approved",_=>status});q.Parameters.AddWithValue("request",request);q.Parameters.AddWithValue("ticket",id);await q.ExecuteNonQueryAsync(ct);}
  await Activity(conn,tx,c,id,status,null,ct);var after=(await Get(conn,tx,c,id,ct))!;await AuditRepository.AppendAsync(conn,tx,c,status,"equipment-ticket",id,before,after,ct);return after;
 }
}
